content.text:
{
  "name": "PI C-867双轴压电定位平台控制器",
  "name_en": "PI C-867 Dual-Axis Piezo Positioning Controller",
  "manufacturer": "Physik Instrumente (PI)",
  "description": "该设备是用于双轴压电定位平台的运动控制器，可通过串口设置伺服、回参考、设定速度并执行X/Y精密移动与位置读取，常用于显微成像等实验中的样品精密扫描与对准。",
  "description_en": "This device is a motion controller for a dual-axis piezo positioning stage. It communicates over serial commands to enable servo control, perform referencing, set velocity, execute precise X/Y motion, and read back position, commonly for sample scanning and alignment in microscopy and other precision lab experiments.",
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭设备连接。",
      "description_en": "Close the device connection."
    },
    {
      "action_name": "auto-SetServo",
      "description": "启用或禁用伺服控制。",
      "description_en": "Enable or disable servo control."
    },
    {
      "action_name": "auto-ReInit",
      "description": "重新初始化控制器，并可执行参考点回零。",
      "description_en": "Reinitialize the controller and optionally perform a reference move."
    },
    {
      "action_name": "auto-SetVelocity",
      "description": "设置指定通道的运动速度。",
      "description_en": "Set the motion velocity for the specified channel."
    },
    {
      "action_name": "auto-GetVelocity",
      "description": "获取指定通道的运动速度。",
      "description_en": "Get the motion velocity for the specified channel."
    },
    {
      "action_name": "auto-MoveTo",
      "description": "将指定通道移动到目标位置。",
      "description_en": "Move the specified channel to a target position."
    },
    {
      "action_name": "auto-MoveToXY",
      "description": "将X/Y双轴移动到目标位置。",
      "description_en": "Move the X/Y axes to target positions."
    },
    {
      "action_name": "auto-GetPos",
      "description": "获取指定通道的当前位置。",
      "description_en": "Get the current position of the specified channel."
    },
    {
      "action_name": "auto-GetPosXY",
      "description": "获取X/Y双轴的当前位置。",
      "description_en": "Get the current positions of the X/Y axes."
    },
    {
      "action_name": "auto-MoveInDir",
      "description": "按给定方向执行连续运动。",
      "description_en": "Perform motion in a specified direction."
    },
    {
      "action_name": "auto-StopMove",
      "description": "停止当前运动。",
      "description_en": "Stop the current motion."
    },
    {
      "action_name": "auto-GetControlReady",
      "description": "获取控制器是否处于就绪状态。",
      "description_en": "Get whether the controller is ready."
    },
    {
      "action_name": "auto-GetChannelObject",
      "description": "获取通道对象信息。",
      "description_en": "Get the channel object information."
    },
    {
      "action_name": "auto-GetChannelPhase",
      "description": "获取通道相位信息。",
      "description_en": "Get the channel phase information."
    },
    {
      "action_name": "auto-GetMin",
      "description": "获取指定通道的最小位置范围。",
      "description_en": "Get the minimum position limit for the specified channel."
    },
    {
      "action_name": "auto-GetMax",
      "description": "获取指定通道的最大位置范围。",
      "description_en": "Get the maximum position limit for the specified channel."
    },
    {
      "action_name": "auto-OnTarget",
      "description": "获取设备是否到达目标位置。",
      "description_en": "Get whether the device is on target."
    },
    {
      "action_name": "auto-GetFirmwareVersion",
      "description": "获取控制器固件版本。",
      "description_en": "Get the controller firmware version."
    }
  ],
  "tag_hints": [
    "piezo positioning",
    "XY stage control",
    "precision motion control",
    "servo positioning",
    "serial instrument control",
    "microscopy sample scanning",
    "reference homing"
  ]
}

